APX.pe = {"country":{"name":"Peru","tagline":"The cradle of South American wine, where desert vineyards once supplied an empire and now feed pisco stills.","classification":"Peru has no wine appellation system comparable to Chile's or Argentina's. The protected name that matters is the denomination of origin *Pisco*, established in 1991, which covers the coastal valleys of Lima, Ica, Arequipa, Moquegua and Tacna (Locumba, Sama and Caplina valleys) and specifies eight pisco grapes (Quebranta, Negra Criolla, Mollar, Uvina, Italia, Torontel, Moscatel and Albilla) and production rules. Peru contests Chile's use of the name pisco, which Chile protected in its own law in 1931; international recognition is split between the two countries. Wine labels may name valleys or regions without a formal appellation."},"regions":[{"name":"Ica","slug":"ica","tagline":"Peru's desert heartland of wine and pisco.","ids":["pe-ica"]},{"name":"Arequipa","slug":"arequipa","tagline":"","ids":["pe-arequipa"]},{"name":"Lima","slug":"lima","tagline":"","ids":["pe-lima"]},{"name":"Moquegua","slug":"moquegua","tagline":"","ids":["pe-moquegua"]},{"name":"Tacna","slug":"tacna","tagline":"","ids":["pe-tacna"]}],"items":{"pe-arequipa":{"name":"Arequipa","cat":"Region","subcat":"Pisco DO zone","region":"Arequipa","styles":["red","white","sweet"],"summary":"Arequipa's wine valleys (Majes, Vítor, Caravelí) were colonial vineyards supplying the mines of Upper Peru; today they produce pisco and a revival of traditional wines from old Negra Criolla vines in desert valleys at 500 to 1,800 m.","rslug":"arequipa"},"pe-ica":{"name":"Ica","cat":"Region","subcat":"Pisco DO zone","region":"Ica","styles":["red","white","sweet","fortified"],"summary":"Ica, about 300 km south of Lima, is the heart of Peruvian wine and pisco: a desert valley with roughly half the country's production, about 400 to 500 m above sea level, irrigated by the Ica river and wells. It holds the colonial-era Hacienda Tacama, Viña Ocucaje (1898), Santiago Queirolo's estate and Intipalka, and the Tabernero group is based in nearby Chincha. Hot days and cool, foggy nights give ripe reds such as Malbec, Tannat and Petit Verdot, while Quebranta and the aromatic grapes go to pisco.","producers":["Tacama","Ocucaje","Santiago Queirolo (Intipalka)","Tabernero","Vista Alegre"],"nerd_note":"Ica's Huacachina oasis, a lagoon among giant dunes 5 km from the city, is the tourist centre of Peru's wine route.","rslug":"ica"},"pe-lima":{"name":"Lima","cat":"Region","subcat":"Pisco DO zone","region":"Lima","styles":["red","white","sweet"],"summary":"Lima region's wine and pisco valleys lie south of the capital in Cañete, around Lunahuaná and Azpitia, where small producers make pisco, artisanal wine and *cachina* (young, partly fermented grape wine) on terraces along the Cañete river.","rslug":"lima"},"pe-moquegua":{"name":"Moquegua","cat":"Region","subcat":"Pisco DO zone","region":"Moquegua","styles":["sweet","red"],"summary":"Moquegua was one of the great wine valleys of the viceroyalty; archaeologists have mapped dozens of colonial *bodegas* with clay jars in its desert valley. It is a pisco DO region with small, traditional producers.","nerd_note":"Archaeological surveys have documented dozens of colonial winery sites, with their clay botijas, in the Moquegua valley.","rslug":"moquegua"},"pe-tacna":{"name":"Tacna","cat":"Region","subcat":"Pisco DO zone","region":"Tacna","styles":["sweet","red"],"summary":"Tacna, on the Chilean border, has pisco DO status in the Locumba, Sama and Caplina valleys, with small vineyards for pisco and local wine.","rslug":"tacna"}}};
